// Flint Markdown Export demo: shows a sample Confluence page tree next to the export it
// produces. sample.json is generated by the app's own exporter; nothing is converted here.
const root = document.getElementById('md-demo');
const base = new URL('./', document.baseURI);

const escapeHtml = (text) => String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

function el(tag, attrs = {}, ...children) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(attrs)) {
    if (key === 'class') node.className = value;
    else if (key.startsWith('on')) node.addEventListener(key.slice(2), value);
    else node.setAttribute(key, value);
  }
  for (const child of children) node.append(child);
  return node;
}

// Front matter, relative links, alerts and fences get their own colors so the parts that make
// the export useful stand out.
function highlight(text) {
  const lines = text.split('\n');
  let inFrontMatter = lines[0] === '---';
  let inFence = false;
  return lines.map((line, index) => {
    const safe = escapeHtml(line);
    if (inFrontMatter) {
      if (index > 0 && line === '---') inFrontMatter = false;
      const match = /^([a-z_]+):(.*)$/.exec(line);
      return match ? `<span class="fm"><span class="fm-key">${match[1]}:</span>${escapeHtml(match[2])}</span>` : `<span class="fm">${safe}</span>`;
    }
    if (/^(`{3,}|~{3,})/.test(line)) {
      inFence = !inFence;
      return `<span class="fence">${safe}</span>`;
    }
    if (inFence) return `<span class="code">${safe}</span>`;
    if (/^#{1,6} /.test(line)) return `<span class="heading">${safe}</span>`;
    if (/^&gt; \[!/.test(safe)) return `<span class="alert">${safe}</span>`;
    return safe.replace(/\]\(((?!https?:)[^)\s]+)\)/g, '](<span class="rel" title="Relative link to an exported file">$1</span>)');
  }).join('\n');
}

// A page's file comes first, then its children's folder, then its assets folder.
function sortKey(name, isDir) {
  const stem = name.replace(/\.md$/, '').replace(/\.assets$/, '');
  const rank = isDir ? (name.endsWith('.assets') ? 2 : 1) : 0;
  return `${stem}\u0000${rank}`;
}

function buildTree(files) {
  const tree = { dirs: new Map(), files: [] };
  for (const file of files) {
    const parts = file.path.split('/');
    let node = tree;
    for (const part of parts.slice(0, -1)) {
      if (!node.dirs.has(part)) node.dirs.set(part, { dirs: new Map(), files: [] });
      node = node.dirs.get(part);
    }
    node.files.push({ name: parts.at(-1), file });
  }
  return tree;
}

function start(data) {
  const pageByFile = new Map(data.pages.map((page) => [page.file, page]));
  const fileByPath = new Map(data.files.map((file) => [file.path, file]));
  const fileButtons = new Map();
  const pageButtons = new Map();

  const confluenceTitle = el('h3');
  const confluenceBody = el('div', { class: 'md-confluence-body' });
  const codePath = el('div', { class: 'md-code-path' });
  const code = el('pre', { class: 'md-code', tabindex: '0' });

  function showPage(id, syncFile = true) {
    const page = data.pages.find((candidate) => candidate.id === id);
    for (const [key, button] of pageButtons) button.setAttribute('aria-current', String(key === id));
    confluenceTitle.textContent = page.title;
    confluenceBody.innerHTML = page.html;
    if (syncFile) showFile(page.file);
  }

  function showFile(path) {
    const file = fileByPath.get(path);
    for (const [key, button] of fileButtons) button.setAttribute('aria-current', String(key === path));
    codePath.textContent = `${data.top}/${path}`;
    if (file.text !== undefined) {
      code.innerHTML = highlight(file.text);
    } else {
      code.replaceChildren(el('img', { src: new URL(`sample/${data.top}/${path}`, base).href, alt: path.split('/').at(-1) }));
    }
    code.scrollTop = 0;
    const page = pageByFile.get(path);
    if (page) showPage(page.id, false);
  }

  // Links between sample pages switch the selection; other sample links go nowhere.
  confluenceBody.addEventListener('click', (event) => {
    const anchor = event.target.closest('a');
    if (!anchor) return;
    event.preventDefault();
    const target = /#page-(\d+)$/.exec(anchor.getAttribute('href') ?? '');
    if (target) showPage(target[1]);
  });

  const pageNav = el('ul', { class: 'md-page-nav' });
  for (const page of data.pages) {
    const button = el('button', { type: 'button', style: `padding-left:${10 + page.depth * 16}px`, onclick: () => showPage(page.id) }, page.title);
    pageButtons.set(page.id, button);
    pageNav.append(el('li', {}, button));
  }

  const fileNav = el('ul', { class: 'md-file-nav' });
  const special = (entry, depth) => (depth === 0 && entry.file ? ({ 'manifest.json': 1, 'all-pages.md': 2 }[entry.name] ?? 0) : 0);
  const renderTree = (node, depth) => {
    const entries = [
      ...[...node.dirs.keys()].map((name) => ({ name, dir: node.dirs.get(name) })),
      ...node.files.map((entry) => ({ name: entry.name, file: entry.file })),
    ].sort((a, b) => special(a, depth) - special(b, depth) || sortKey(a.name, Boolean(a.dir)).localeCompare(sortKey(b.name, Boolean(b.dir))));
    for (const entry of entries) {
      const indent = `padding-left:${10 + depth * 16}px`;
      if (entry.dir) {
        fileNav.append(el('li', { class: 'md-dir', style: indent }, `${entry.name}/`));
        renderTree(entry.dir, depth + 1);
      } else {
        const button = el('button', { type: 'button', style: indent, onclick: () => showFile(entry.file.path) }, entry.name);
        fileButtons.set(entry.file.path, button);
        fileNav.append(el('li', {}, button));
      }
    }
  };
  renderTree(buildTree(data.files), 0);

  const { pages, images, warnings } = data.summary;
  root.replaceChildren(
    el('div', { class: 'md-demo-bar' },
      el('span', {}, `${pages} pages, ${images} ${images === 1 ? 'image' : 'images'}, ${warnings} warnings`),
      el('a', { class: 'button', href: new URL(data.zipName, base).href, download: data.zipName }, 'Download the sample ZIP ', el('span', { 'aria-hidden': 'true' }, '↓'))),
    el('div', { class: 'md-demo-panes' },
      el('section', { class: 'md-pane', 'aria-label': 'In Confluence' },
        el('p', { class: 'md-pane-label' }, 'IN CONFLUENCE'),
        el('div', { class: 'md-pane-grid' },
          el('nav', { 'aria-label': 'Sample pages' }, pageNav),
          el('div', { class: 'md-confluence' }, confluenceTitle, confluenceBody))),
      el('section', { class: 'md-pane md-pane-dark', 'aria-label': 'In the ZIP' },
        el('p', { class: 'md-pane-label' }, 'IN THE ZIP'),
        el('div', { class: 'md-pane-grid' },
          el('nav', { 'aria-label': 'Exported files' }, el('div', { class: 'md-dir' }, `${data.top}/`), fileNav),
          el('div', { class: 'md-viewer' }, codePath, code)))),
  );
  showPage(data.pages[0].id);
}

// On failure the page keeps its static download link.
fetch(new URL('sample.json', base))
  .then((response) => {
    if (!response.ok) throw new Error(`sample.json returned ${response.status}`);
    return response.json();
  })
  .then(start)
  .catch(() => {});
